package com.hbm.entity.mob.maskman;
import com.hbm.armor.GasMaskFilters;import com.hbm.item.survivalloot.SurvivalLootContent;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.nbt.CompoundTag;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.*;import net.minecraft.tags.DamageTypeTags;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.entity.ai.goal.*;import net.minecraft.world.entity.ai.goal.target.*;import net.minecraft.world.entity.monster.Monster;import net.minecraft.world.entity.player.Player;import net.minecraft.world.entity.projectile.ThrownEgg;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;
/** Actual X5846 EntityMaskMan; ranged-only source AI, no invented melee attack. */
public final class MaskMan extends Monster {
 private float previousHealth=1000;
 private final net.minecraft.server.level.ServerBossEvent boss=new ServerBossEvent(getDisplayName(),net.minecraft.world.BossEvent.BossBarColor.PURPLE,net.minecraft.world.BossEvent.BossBarOverlay.PROGRESS);
 public MaskMan(EntityType<? extends MaskMan> type,Level level){super(type,level);xpReward=100;setPersistenceRequired();boss.setDarkenScreen(true);}
 public static AttributeSupplier.Builder attributes(){return Monster.createMonsterAttributes().add(Attributes.MOVEMENT_SPEED,.25).add(Attributes.FOLLOW_RANGE,100).add(Attributes.ATTACK_DAMAGE,15).add(Attributes.KNOCKBACK_RESISTANCE,1).add(Attributes.MAX_HEALTH,1000);}
 @Override protected void registerGoals(){goalSelector.addGoal(1,new FloatGoal(this));goalSelector.addGoal(2,new MaskManApproachGoal(this));goalSelector.addGoal(2,new MaskManMinigunGoal(this));goalSelector.addGoal(3,new MaskManLaserGoal(this));goalSelector.addGoal(3,new RandomStrollGoal(this,1));goalSelector.addGoal(4,new RandomLookAroundGoal(this));goalSelector.addGoal(5,new LookAtPlayerGoal(this,Player.class,8));targetSelector.addGoal(1,new HurtByTargetGoal(this));targetSelector.addGoal(2,new NearestAttackableTargetGoal<>(this,Player.class,0,true,false,null));}
 @Override public boolean removeWhenFarAway(double distance){return false;}
 @Override public boolean hurt(DamageSource source,float amount){if(source.getDirectEntity() instanceof ThrownEgg&&random.nextInt(10)==0){xpReward=0;setHealth(0);return true;}if(source.is(DamageTypeTags.IS_FIRE)||source.is(net.minecraft.tags.TagKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,ResourceLocation.parse("hbm:legacy_magic"))))amount=0;if(source.is(DamageTypeTags.IS_PROJECTILE))amount*=.5F;if(source.is(DamageTypeTags.IS_EXPLOSION))amount*=.5F;if(amount>50)amount=50+(amount-50)*.5F;float before=getHealth();boolean full=invulnerableTime<=10;boolean result=super.hurt(source,amount);if(result&&full)previousHealth=before;return result;}
 @Override public void tick(){super.tick();if(previousHealth>=getMaxHealth()/2&&getHealth()<getMaxHealth()/2&&isAlive()){previousHealth=getHealth();if(!level().isClientSide)level().explode(this,getX(),getY()+4,getZ(),2.5F,false,Level.ExplosionInteraction.BLOCK);}if(!level().isClientSide){boss.setName(getDisplayName());boss.setProgress(getHealth()/getMaxHealth());}}
 @Override public void startSeenByPlayer(ServerPlayer player){super.startSeenByPlayer(player);boss.addPlayer(player);}@Override public void stopSeenByPlayer(ServerPlayer player){super.stopSeenByPlayer(player);boss.removePlayer(player);}
 @Override protected void dropCustomDeathLoot(ServerLevel level,DamageSource source,boolean recent){var mask=new ItemStack(SurvivalLootContent.M65.get());var filter=BuiltInRegistries.ITEM.get(ResourceLocation.parse("hbm:gas_mask_filter_combo"));GasMaskFilters.install(mask,new ItemStack(filter),registryAccess());spawnAtLocation(mask,0);spawnAtLocation(MaskManContent.COIN.get());spawnAtLocation(MaskManContent.CLOUD.get());spawnAtLocation(Items.SKELETON_SKULL);}
 @Override public void readAdditionalSaveData(CompoundTag tag){super.readAdditionalSaveData(tag);previousHealth=getHealth();boss.setName(getDisplayName());}
}
